query:
mutation networkConfigSnmpDeleteProfileList ( $accountId:ID! $networkConfigSnmpDeleteProfileListInput:NetworkConfigSnmpDeleteProfileListInput!) {
	networkConfig ( accountId:$accountId ) {
		snmp {
			deleteProfileList ( input:$networkConfigSnmpDeleteProfileListInput   ) {
				snmpProfile {
					id
					name
					username
					securityLevel
					authProtocol
					privacyProtocol
					description
					audit {
						updatedTime
						updatedBy {
							id
							name
						}
					}
				}
			}
		}
	}	
}
